//! The envelope vectors shared with the Pipeline app (PL-025, design step 1):
//! `interop/vectors/envelope-vectors.json`. The app's sync-core tests read the same file, from the
//! `ffi-v` release that carries it, so both implementations hash and reject the same envelopes.
//!
//! The file is generated by `vectors()` below and checked in. After a deliberate change, rewrite it
//! with `BLESS=1 cargo test -p broadcast --test envelope_vectors`.

use broadcast::envelope::{DeviceId, EventEnvelope, Hash};
use iroh::{PublicKey, SecretKey, Signature};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::path::PathBuf;

#[derive(Debug, PartialEq, Serialize, Deserialize)]
struct Vectors {
    comment: Vec<String>,
    keys: BTreeMap<String, Key>,
    cases: Vec<Case>,
}

#[derive(Debug, PartialEq, Serialize, Deserialize)]
struct Key {
    secret: String,
    public: String,
}

#[derive(Debug, PartialEq, Serialize, Deserialize)]
struct Case {
    name: String,
    /// `valid`, or why the envelope must be rejected: `hash` (its contents don't produce its
    /// hash), `device-id` (its device id contains `|`) or `signature` (contents fine, signature
    /// not `signer`'s over them).
    expect: String,
    envelope: EventEnvelope,
    signer: String,
    signature: String,
}

fn path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../interop/vectors/envelope-vectors.json")
}

fn hex(bytes: &[u8]) -> String {
    data_encoding::HEXLOWER.encode(bytes)
}

fn secret(seed: u8) -> SecretKey {
    SecretKey::from_bytes(&[seed; 32])
}

fn vectors() -> Vectors {
    let a = secret(0xa1);
    let b = secret(0xb2);
    let phone = DeviceId::new("0199f3b4-7c1e-7a10-9f6e-3d2c1b0a9f8e".into());
    let desktop = DeviceId::new("0199f3b4-9e2d-7b20-8a5f-4e3d2c1b0a9f".into());

    let mut cases = Vec::new();
    let mut case = |name: &str, expect: &str, envelope: EventEnvelope, signer: &str, signature: Signature| {
        cases.push(Case {
            name: name.into(),
            expect: expect.into(),
            envelope,
            signer: signer.into(),
            signature: hex(&signature.to_bytes()),
        });
    };
    let signed = |envelope: &EventEnvelope, key: &SecretKey| envelope.sign(key).expect("sealed");

    // The app's EnvelopeHashTest golden vector. Its parents aren't real hashes, which the hash
    // doesn't care about.
    let golden = EventEnvelope::seal(
        DeviceId::new("device-a".into()),
        3,
        1000,
        vec![Hash::new("abc".into()), Hash::new("def".into())],
        r#"{"type":"x","note":"café"}"#.into(),
    );
    case("app-golden", "valid", golden.clone(), "a", signed(&golden, &a));

    let first = EventEnvelope::seal(
        phone.clone(),
        0,
        1_760_000_000_000,
        vec![],
        r#"{"type":"org.cr.pipeline.sync.event.ApplicationCreated","applicationId":{"value":"7d0c"},"input":{"company":"Acme","role":"Engineer"}}"#.into(),
    );
    case("first-event", "valid", first.clone(), "a", signed(&first, &a));

    let second = EventEnvelope::seal(
        phone.clone(),
        1,
        1_760_000_060_000,
        vec![first.hash.clone()],
        r#"{"type":"org.cr.pipeline.sync.event.StatusChanged","applicationId":{"value":"7d0c"},"status":"INTERVIEWING"}"#.into(),
    );
    case("chained", "valid", second.clone(), "a", signed(&second, &a));

    let desktop_first = EventEnvelope::seal(desktop.clone(), 0, 1_760_000_030_000, vec![], "{}".into());
    case("other-device-first", "valid", desktop_first.clone(), "b", signed(&desktop_first, &b));

    // Causal parents (design § Causal parents): the device's own previous event, then the latest
    // event it folded from another device.
    let causal = EventEnvelope::seal(
        phone.clone(),
        2,
        1_760_000_120_000,
        vec![second.hash.clone(), desktop_first.hash.clone()],
        r#"{"type":"org.cr.pipeline.sync.event.ApplicationEdited"}"#.into(),
    );
    case("causal-parents", "valid", causal.clone(), "a", signed(&causal, &a));

    let empty = EventEnvelope::seal(phone.clone(), 3, 1_760_000_180_000, vec![causal.hash.clone()], "".into());
    case("empty-payload", "valid", empty.clone(), "a", signed(&empty, &a));

    // Separators, a newline, and characters outside the BMP: UTF-16 surrogate pairs in Kotlin,
    // four UTF-8 bytes in both.
    let awkward = EventEnvelope::seal(
        phone.clone(),
        4,
        1_760_000_240_000,
        vec![empty.hash.clone()],
        "a|b,c\n|é 日本 🎉 𝄞".into(),
    );
    case("awkward-payload", "valid", awkward.clone(), "a", signed(&awkward, &a));

    // Above 2^53, so a JSON reader that goes through a double gets it wrong.
    let large = EventEnvelope::seal(phone.clone(), 9_007_199_254_740_993, 253_402_300_799_999, vec![], "{}".into());
    case("large-numbers", "valid", large.clone(), "a", signed(&large, &a));

    let tampered = EventEnvelope { payload: second.payload.replace("INTERVIEWING", "OFFER"), ..second.clone() };
    case("tampered-payload", "hash", tampered, "a", signed(&second, &a));

    let dropped = EventEnvelope { parent_hashes: vec![second.hash.clone()], ..causal.clone() };
    case("parent-dropped", "hash", dropped, "a", signed(&causal, &a));

    let reordered =
        EventEnvelope { parent_hashes: vec![desktop_first.hash.clone(), second.hash.clone()], ..causal.clone() };
    case("parents-reordered", "hash", reordered, "a", signed(&causal, &a));

    let resequenced = EventEnvelope { sequence: 2, ..second.clone() };
    case("sequence-changed", "hash", resequenced, "a", signed(&second, &a));

    let uppercase = EventEnvelope { hash: Hash::new(first.hash.as_str().to_uppercase()), ..first.clone() };
    case("hash-uppercase", "hash", uppercase, "a", signed(&first, &a));

    let piped = EventEnvelope::seal(DeviceId::new("device-a|3".into()), 1000, 0, vec![], "{}".into());
    case("device-id-with-separator", "device-id", piped.clone(), "a", signed(&piped, &a));

    case("signed-by-another-key", "signature", second.clone(), "a", signed(&second, &b));
    case("signature-of-another-envelope", "signature", second.clone(), "a", signed(&first, &a));
    let mut flipped = signed(&second, &a).to_bytes();
    flipped[0] ^= 1;
    case("signature-bit-flipped", "signature", second.clone(), "a", Signature::from_bytes(&flipped));

    let keys = [("a", &a), ("b", &b)]
        .into_iter()
        .map(|(name, key)| {
            (name.to_string(), Key { secret: hex(&key.to_bytes()), public: hex(key.public().as_bytes()) })
        })
        .collect();

    Vectors {
        comment: vec![
            "Envelope vectors shared by pipeline-sync and the Pipeline app (PL-025, design step 1).".into(),
            "hash = lowercase hex SHA-256 of UTF-8 `deviceId|sequence|timestamp|` + each parent + `,` + `|payload`.".into(),
            "signature = ed25519 by the signer's key over the 32 bytes the hash names, in hex.".into(),
            "expect: valid, or the rejection: hash, device-id, signature.".into(),
            "Generated by crates/broadcast/tests/envelope_vectors.rs; do not edit by hand.".into(),
        ],
        keys,
        cases,
    }
}

fn read() -> Vectors {
    let text = std::fs::read_to_string(path()).expect("vector file");
    serde_json::from_str(&text).expect("vector file parses")
}

#[test]
fn the_file_is_current() {
    let generated = serde_json::to_string_pretty(&vectors()).unwrap() + "\n";
    if std::env::var_os("BLESS").is_some() {
        std::fs::write(path(), &generated).unwrap();
    }
    let on_disk = std::fs::read_to_string(path()).expect("vector file; generate it with BLESS=1");
    assert_eq!(on_disk, generated, "the vector file is stale; regenerate it with BLESS=1");
}

#[test]
fn the_apps_golden_hash_is_in_the_file() {
    let vectors = read();
    let golden = vectors.cases.iter().find(|case| case.name == "app-golden").unwrap();
    assert_eq!(golden.envelope.hash.as_str(), "43f813844e8cc8d052c5f03a8c69e5a3903729589bac124f7b8d30709f1995a1");
}

#[test]
fn every_case_is_accepted_or_rejected_as_it_says() {
    let vectors = read();
    for case in &vectors.cases {
        let key = &vectors.keys[&case.signer];
        let public = PublicKey::from_bytes(&data_encoding::HEXLOWER.decode(key.public.as_bytes()).unwrap().try_into().unwrap())
            .unwrap();
        let signature = Signature::try_from(data_encoding::HEXLOWER.decode(case.signature.as_bytes()).unwrap().as_slice())
            .unwrap();
        let contents = case.envelope.verify();
        let signed = case.envelope.verify_signature(&signature, &public);
        let (want_contents, want_signed) = match case.expect.as_str() {
            "valid" => (true, true),
            "hash" | "device-id" => (false, signed),
            "signature" => (true, false),
            other => panic!("{}: unknown expectation {other}", case.name),
        };
        assert_eq!((contents, signed), (want_contents, want_signed), "{}", case.name);
    }
}

#[test]
fn every_kind_of_rejection_is_covered() {
    let vectors = read();
    for expect in ["valid", "hash", "device-id", "signature"] {
        assert!(vectors.cases.iter().any(|case| case.expect == expect), "no {expect} case");
    }
}

#[test]
fn the_keys_are_the_secrets_they_say() {
    for key in read().keys.values() {
        let secret: [u8; 32] = data_encoding::HEXLOWER.decode(key.secret.as_bytes()).unwrap().try_into().unwrap();
        assert_eq!(hex(SecretKey::from_bytes(&secret).public().as_bytes()), key.public);
    }
}
